    m_tools.set_slice_ended([this](const std::string& action_id) { m_ended_slices.push_back(action_id); });
    m_tool_activity_subscription = m_tools.subscribe([this](const ToolActivity& activity) {
        // A client that calls the app's tools is connected, however it was set up.
        if (activity.source == ToolSource::Mcp && m_mcp_connect.connected)
            m_mcp_connect.connected();
        if (m_step_listener && tool_state_terminal(activity.state))
            m_step_listener("tool", activity.tool + " " + tool_state_name(activity.state));
        // A failed call, the in-app Agent's or an MCP client's, leaves a line
        // in the app log; the chat shows it only to the person who opens it.
        if (activity.state == ToolState::Failed && activity.error)
            BOOST_LOG_TRIVIAL(warning) << "JusPrin tool call failed: " << activity.tool << " ("
                                       << (activity.source == ToolSource::Mcp ? "mcp" : "agent") << ", "
                                       << activity.action_id << "): " << activity.error->code << ": "
                                       << activity.error->message;
        if (activity.state == ToolState::Failed && activity.error && m_unexpected_error_handler &&
            (activity.error->code == "failed" || activity.error->code == "local_save_failed"))
            m_unexpected_error_handler("running the tool " + activity.tool,
                                       std::make_exception_ptr(ToolCallFailure(activity.error->code + ": " + activity.error->message)));
        // The last word of an action that replaced the project belongs to the
        // project it closed, not to the one now open.
        if (activity.session != m_workspace.snapshot().session.value())
            return;
        m_persistence.document().upsert_activity(activity, m_persistence.timestamp());
        if (tool_state_terminal(activity.state))
            m_persistence.flush();
        else
            m_persistence.commit();
        if (m_handshake)
            send_tool_activity(activity);

