361	bool system_refused(const std::filesystem::filesystem_error& error, const std::filesystem::path& folder)
362	{
363	    const std::error_code code = error.code();
364	    if (code != std::errc::permission_denied && code != std::errc::operation_not_permitted &&
365	        code != std::errc::read_only_file_system && code != std::errc::no_space_on_device)
366	        return false;
367	    const std::filesystem::path& path = error.path1().empty() ? error.path2() : error.path1();
368	    const std::filesystem::path  inside = path.lexically_normal().lexically_relative(folder.lexically_normal());
369	    return !path.empty() && !inside.empty() && *inside.begin() != "..";
370	}
