407	std::string ProjectAutosave::observed_input() const
408	{
409	    // Only native printable project state belongs in checkpoint detection.
410	    // Conversation, plans, intent, audit, and print facts are durable in the
411	    // current document and cannot force a model export.
412	    // The scan touches identities, timestamps and small metadata, never mesh
413	    // triangles or Orca's 3MF writer.
414	    std::ostringstream out;
415	    out << std::setprecision(17) << m_event_sequence << ';';
416	    append_text(out, m_persistence.document().project_id());
417	    append_text(out, m_plater.get_project_name().ToUTF8().data());
418	    append_text(out, m_plater.get_project_filename(".3mf").ToUTF8().data());
419	    const Model& model = m_plater.model();
420	    out << model.id().id << ';' << model.objects.size() << ';';
421	    // The record's contents, not whether it exists: OrcaSlicer's project
422	    // info panel makes an empty one whenever it refreshes, which holds
423	    // nothing new to save.
424	    const ModelInfo no_info;
425	    const ModelInfo& info = model.model_info ? *model.model_info : no_info;
426	    append_text(out, info.cover_file);
427	    append_text(out, info.description);
428	    append_text(out, info.model_name);
429	    for (const auto& [plate_index, codes] : model.plates_custom_gcodes) {
430	        out << plate_index << ',' << int(codes.mode) << ',' << codes.gcodes.size() << ';';
431	        for (const auto& code : codes.gcodes) {
432	            out << code.print_z << ',' << int(code.type) << ',' << code.extruder << ';';
433	            append_text(out, code.color);
434	            append_text(out, code.extra);
435	        }
436	    }
437	    for (const ModelObject* object : model.objects) {
438	        out << object->id().id << ',' << object->printable << ',' << object->auto_drop << ','
439	            << static_cast<const ModelConfig&>(object->config).timestamp()
440	            << ',' << object->layer_height_profile.timestamp() << ';';
441	        append_text(out, object->name);
442	        out << object->brim_points.size() << ';';
443	        for (const auto& point : object->brim_points)
444	            out << point.pos.x() << ',' << point.pos.y() << ',' << point.pos.z() << ',' << point.head_front_radius << ';';
445	        out << object->volumes.size() << ';';
446	        for (const ModelVolume* volume : object->volumes) {
447	            out << volume->id().id << ',' << volume->mesh_ptr().get() << ',' << int(volume->type())
448	                << ',' << static_cast<const ModelConfig&>(volume->config).timestamp()
449	                << ',' << volume->supported_facets.timestamp()
450	                << ',' << volume->seam_facets.timestamp() << ',' << volume->mmu_segmentation_facets.timestamp()
451	                << ',' << volume->fuzzy_skin_facets.timestamp() << ';';
452	            append_text(out, volume->name);
453	            append_text(out, volume->material_id());
454	            append_transform(out, volume->get_matrix());
455	        }
456	        out << object->instances.size() << ';';
457	        for (const ModelInstance* instance : object->instances) {
458	            out << instance->id().id << ',' << instance->printable
459	                << ',' << instance->arrange_order << ';';
460	            append_transform(out, instance->get_matrix());
461	        }
462	    }
463	    PartPlateList& plates = m_plater.get_partplate_list();
464	    out << plates.get_plate_count() << ';';
465	    for (int index = 0; index < plates.get_plate_count(); ++index) {
466	        PartPlate* plate = plates.get_plate(index);
467	        out << plate->id().id << ',' << int(plate->get_bed_type()) << ',' << plate->is_locked()
468	            << ',' << int(plate->get_filament_map_mode()) << ';';
469	        append_text(out, plate->get_plate_name());
470	        for (int filament : plate->get_filament_maps()) out << filament << ',';
471	        out << ';';
472	        append_config(out, *plate->config());
473	    }
474	    if (const PresetBundle* presets = wxGetApp().preset_bundle)
475	        append_config(out, presets->full_config_secure());
476	    return out.str();
477	}
478	
479	void ProjectAutosave::trim_history()
480	{
481	    try {
482	        std::set<std::string> live_attachments;
483	        for (const auto& attachment : m_persistence.document().attachments())
484	            if (!attachment.stored_name.empty())
485	                live_attachments.insert(attachment.relative_path());
486	        m_store->prune(kMaxVersions, kMaxBytes, live_attachments);
487	        m_warning.clear();
488	    } catch (const std::exception& error) {
489	        // The current head was already committed. A retention failure leaves
490	        // extra old data and must not misreport the current project as unsaved.
491	        m_warning = std::string("Local history cleanup failed: ") + error.what();
492	        BOOST_LOG_TRIVIAL(warning) << m_warning;
493	    }
494	}
495	
496	bool ProjectAutosave::settle(bool wait)
497	{
498	    if (!m_worker.valid())
499	        return true;
500	    if (!wait && m_worker.wait_for(std::chrono::seconds(0)) != std::future_status::ready)
501	        return false;
502	    try {
503	        m_worker.get();
504	        if (m_worker_kind == WorkerKind::Model) {
505	            m_committed_head = m_store->head_id();
506	            m_last_capture_input = std::move(m_inflight_capture_input);
507	            m_seen_model_input = m_last_capture_input;
508	            trim_history();
509	        }
510	        if (m_worker_kind == WorkerKind::Document)
511	            m_committed_semantic_revision = m_inflight_semantic_revision;
512	        m_worker_kind = WorkerKind::None;
513	        if (m_seen_semantic_revision == m_committed_semantic_revision)
514	            m_first_semantic_edit.reset();
515	        m_error.clear();
516	        m_refusal.clear();
517	        // A main-thread edit may have landed while the worker wrote the
518	        // frozen revision. Probe again before saying the current model is saved.
519	        m_state = State::Saving;
520	        m_next_probe = Clock::now();
521	        return true;
522	    } catch (const std::filesystem::filesystem_error& error) {
523	        m_worker_kind = WorkerKind::None;
524	        m_inflight_capture_input.clear();
525	        refused(error);
526	    } catch (const std::exception& error) {
527	        m_worker_kind = WorkerKind::None;
528	        m_inflight_capture_input.clear();
529	        fail(error.what());
530	        throw;
531	    } catch (...) {
532	        m_worker_kind = WorkerKind::None;
533	        m_inflight_capture_input.clear();
534	        fail("project version writer failed");
535	        throw;
536	    }
537	    return false;
538	}
