540	void ProjectAutosave::adopt_project()
541	{
542	    m_persistence.resolve_pending_boundary();
543	    const std::string id = m_persistence.document().project_id();
544	    if (m_store && m_store->project_id() == id)
545	        return;
546	    settle(true);
547	    discard_if_never_saved();
548	    m_store.reset();
549	    if (id.empty())
550	        throw std::runtime_error("open project has no identity");
551	    m_store = std::make_unique<ProjectVersionStore>(m_root, id);
552	    m_last_capture_input.clear();
553	    m_seen_model_input.clear();
554	    m_inflight_capture_input.clear();
555	    m_committed_head = m_store->head_id();
556	    m_committed_semantic_revision = m_committed_head.empty() ? 0 : m_persistence.document().doc_revision();
557	    m_seen_semantic_revision = m_persistence.document().doc_revision();
558	    m_last_semantic_edit = Clock::now();
559	    m_first_semantic_edit = m_seen_semantic_revision != m_committed_semantic_revision ?
560	        std::optional<Clock::time_point>(m_last_semantic_edit) : std::nullopt;
561	    const auto versions = m_store->history();
562	    m_project_name = versions.empty() ? std::string() : versions.back().project_name;
563	    m_opened_from = versions.empty() ? std::string() : versions.back().opened_from;
564	    m_opened_digest = versions.empty() ? std::string() : versions.back().opened_digest;
565	    if (const std::string file = m_plater.get_project_filename(".3mf").ToUTF8().data(); versions.empty() && !file.empty()) {
566	        m_opened_from = file;
567	        m_opened_digest = file_digest(std::filesystem::u8path(file));
568	    }
569	    m_revision = 0;
570	    for (const auto& version : versions)
571	        m_revision = std::max(m_revision, version.revision);
572	    m_state = State::Saving;
573	    m_next_probe = Clock::now();
574	}
