576	bool ProjectAutosave::capture(bool wait_for_commit)
577	{
578	    if (!m_store)
579	        return false;
580	    std::filesystem::path metadata;
581	    try {
582	        const std::string id = ProjectVersionStore::new_id();
583	        metadata = m_store->pending_metadata_path(id);
584	        ++m_capture_attempts;
585	        const int result = m_plater.export_3mf(boost_path(metadata),
586	                                                SaveStrategy::Backup | SaveStrategy::Silence);
587	        if (result < 0)
588	            throw std::runtime_error("The app could not capture project metadata");
589	        protect_saved_settings(metadata);
590	        const wxString source = m_plater.get_project_filename(".3mf");
591	        auto frozen = m_store->freeze(m_plater.model(), id, ++m_revision, m_persistence.document().dump(),
592	                                      source.ToUTF8().data(), m_persistence.timestamp());
593	        const auto& changes = m_persistence.document().changes();
594	        if (!changes.empty())
595	            frozen.version.change_seq = changes.back().seq;
596	        const auto semantic_revision = m_persistence.document().doc_revision();
597	        m_committed_semantic_revision = semantic_revision;
598	        if (m_seen_semantic_revision == semantic_revision)
599	            m_first_semantic_edit.reset();
600	        const std::string plater_name(m_plater.get_project_name().ToUTF8());
601	        const std::string untitled(_L("Untitled").ToUTF8());
602	        frozen.version.project_name = m_project_name.empty() ? plater_name : m_project_name;
603	        // A project with no name yet takes its first object's. One the store
604	        // already named keeps it: a reopened project's Orca name reads
605	        // Untitled, and its next version must not rename it.
606	        if ((m_project_name.empty() || m_project_name == untitled) && (plater_name.empty() || plater_name == untitled) &&
607	            !m_plater.model().objects.empty())
608	            frozen.version.project_name = std::filesystem::u8path(m_plater.model().objects.front()->name).stem().u8string();
609	        m_project_name = frozen.version.project_name;
610	        // A project adopted before Orca named its file gets it with its first
611	        // version.
612	        if (m_opened_from.empty() && m_store->head_id().empty() && !source.empty()) {
613	            m_opened_from   = source.ToUTF8().data();
614	            m_opened_digest = file_digest(std::filesystem::u8path(m_opened_from));
615	        }
616	        frozen.version.opened_from = m_opened_from;
617	        frozen.version.opened_digest = m_opened_digest;
618	        if (m_store->unchanged(frozen)) {
619	            m_store->discard(frozen);
620	            m_last_capture_input = observed_input();
621	            m_seen_model_input = m_last_capture_input;
622	            m_seen_semantic_revision = semantic_revision;
623	            m_first_semantic_edit.reset();
624	            m_error.clear();
625	            m_refusal.clear();
626	            m_state = State::Saved;
627	            return true;
628	        }
629	        m_state = State::Saving;
630	        if (wait_for_commit) {
631	            m_store->publish(std::move(frozen));
632	            m_committed_head = m_store->head_id();
633	            m_last_capture_input = observed_input();
634	            m_seen_model_input = m_last_capture_input;
635	            m_seen_semantic_revision = semantic_revision;
636	            m_first_semantic_edit.reset();
637	            trim_history();
638	            m_error.clear();
639	            m_refusal.clear();
640	            m_state = State::Saved;
641	        } else {
642	            m_inflight_capture_input = observed_input();
643	            m_seen_model_input = m_inflight_capture_input;
644	            m_inflight_semantic_revision = semantic_revision;
645	            m_worker_kind = WorkerKind::Model;
646	            m_worker = std::async(std::launch::async, [this, frozen = std::move(frozen)]() mutable {
647	                m_store->publish(std::move(frozen));
648	            });
649	        }
650	        return true;
651	    } catch (const std::exception& error) {
652	        m_worker_kind = WorkerKind::None;
653	        if (!metadata.empty())
654	            std::filesystem::remove_all(metadata.parent_path());
655	        if (const auto* refusal = dynamic_cast<const std::filesystem::filesystem_error*>(&error)) {
656	            refused(*refusal);
657	            return false;
658	        }
659	        fail(error.what());
660	        throw;
661	    }
662	}
