699	void ProjectAutosave::tick()
700	{
701	    // A failure of ours is reported when saving goes from working to failing.
702	    // The retries after it are recorded and logged, not reported again, until
703	    // a save succeeds. The state cannot tell: a retry sets it to Saving while
704	    // it runs; the error stays until a save succeeds.
705	    const bool failing = m_state != State::Saved && !m_error.empty() && m_refusal.empty();
706	    try {
707	        adopt_project();
708	        if (!settle(false) && m_worker.valid())
709	            return;
710	        observe_document_change();
711	        const auto now = Clock::now();
712	        if (now < m_next_probe)
713	            return;
714	        m_next_probe = now + kProbeInterval;
715	        if (blank()) {
716	            m_error.clear();
717	            m_refusal.clear();
718	            m_state = State::Saved;
719	            return;
720	        }
721	        const std::string model_input = observed_input();
722	        if (model_input != m_seen_model_input) {
723	            m_seen_model_input = model_input;
724	            m_last_edit = now;
725	            m_state = State::Saving;
726	        }
727	        const bool document_pending = m_persistence.document().doc_revision() != m_committed_semantic_revision;
728	        const bool document_due = document_pending &&
729	            (now - m_last_semantic_edit >= kEditQuietPeriod ||
730	             (m_first_semantic_edit && now - *m_first_semantic_edit >= kSemanticMaxDelay));
731	        // A continuously edited model must not starve the current document.
732	        // Model capture also publishes the document, so a ready model still
733	        // takes precedence until the document's maximum delay is reached.
734	        if (document_due && m_first_semantic_edit && now - *m_first_semantic_edit >= kSemanticMaxDelay) {
735	            persist_document(false);
736	            return;
737	        }
738	        const bool model_pending = m_store->head_id().empty() || model_input != m_last_capture_input;
739	        const bool held          = model_pending && m_capture_hold && m_capture_hold();
740	        if (model_pending && !held) {
741	            GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
742	            if (canvas == nullptr || !canvas->is_initialized() ||
743	                canvas->get_gizmos_manager().is_in_editing_mode(true) ||
744	                now - m_last_edit < kEditQuietPeriod)
745	                return;
746	            capture(false);
747	        } else if (document_pending) {
748	            if (!document_due)
749	                return;
750	            persist_document(false);
751	        } else if (!held) {
752	            // Nothing is left to save, so an earlier failure no longer holds.
753	            m_error.clear();
754	            m_refusal.clear();
755	            m_state = State::Saved;
756	            m_first_semantic_edit.reset();
757	        }
758	    } catch (const std::exception& error) {
759	        const auto* refusal = dynamic_cast<const std::filesystem::filesystem_error*>(&error);
760	        if (refusal != nullptr && system_refused(*refusal, m_root)) {
761	            refused(*refusal);
762	            return;
763	        }
764	        fail(error.what());
765	        if (!failing)
766	            throw;
767	    }
768	}
