void LeftPane::export_project()
{
    if (m_sources.autosave == nullptr)
        return;
    wxFileDialog dialog(this, _L("Export project 3MF"), {}, "JusPrin project.3mf", _L("3MF files") + " (*.3mf)|*.3mf",
                        wxFD_SAVE | wxFD_OVERWRITE_PROMPT);
    if (dialog.ShowModal() != wxID_OK)
        return;
    const std::filesystem::path destination(dialog.GetPath().ToStdWstring());
    // A name that does not end in .3mf is the person's to change.
    if (!boost::iequals(destination.extension().u8string(), ".3mf")) {
        show_project_error(_L("Export failed"), _L("The project couldn't be exported. Try again."), "the name does not end in .3mf");
        return;
    }
    // Anything else that fails is ours, and goes up to the handler that
    // reports it.
    try {
        // The project is saved first; the system refused that save.
        if (!m_sources.autosave->export_copy(destination)) {
            const std::string& refusal = m_sources.autosave->refusal();
            m_sources.autosave->tell_refusal();
            show_project_error(_L("Export failed"),
                               refusal.empty() ? _L("The project couldn't be exported. Try again.")
                                               : wxString::FromUTF8(said_by(kSystemName, refusal)),
                               m_sources.autosave->error());
        }
    } catch (const std::filesystem::filesystem_error& error) {
        // The chosen folder refused the copy; any other file system error is ours.
        if (!system_refused(error, destination.parent_path()))
            throw;
        show_project_error(_L("Export failed"),
                           wxString::FromUTF8(said_by(kSystemName, error.path1().parent_path().u8string() + ": " + error.code().message())),
                           error.what());
    }
}

void LeftPane::restore_version(const std::string& version_id)
{
    if (m_sources.autosave == nullptr)
        return;
    const bool confirmed = m_sources.confirm_restore ? m_sources.confirm_restore() : [this] {
        wxMessageDialog confirmation(this,
            _L("Restore this version of the model and project settings? The current model will be saved "
               "as a version first. Conversations and print records will stay current."),
            _L("Restore project version"), wxYES_NO | wxICON_QUESTION);
        confirmation.SetYesNoLabels(_L("Restore"), _L("Cancel"));
        return OrcaMessages::show_own_modal(confirmation) == wxID_YES;
    }();
    if (!confirmed)
        return;
    // The current model is saved first, and the system may refuse that save.
    // Any other failure reads or writes the app's own folder: it is ours.
    if (!m_sources.autosave->restore(version_id)) {
        if (m_sources.autosave->refusal().empty())
            throw std::runtime_error(m_sources.autosave->error());
        m_sources.autosave->tell_refusal();
        show_project_error(_L("Restore failed"), wxString::FromUTF8(said_by(kSystemName, m_sources.autosave->refusal())),
                           m_sources.autosave->error());
    }
    // A restore replaces the project, so whatever was open belongs to the old one.
    refresh_from_workspace();
}

