import sys
ROOT = '/Users/kenneth/Projects/JusPrin/'

def edit(path, pairs):
    p = ROOT + path
    s = open(p, encoding='utf-8').read()
    for old, new in pairs:
        if s.count(old) != 1:
            sys.exit(f'{path}: expected one match, found {s.count(old)}:\n{old}')
        s = s.replace(old, new)
