#pragma once

// --dialog-witness <directory>: says on stderr which of OrcaSlicer's dialogs
// reached the screen, pictures each one, and then closes it with the answer
// that changes least, as a person who dismissed it would. A dialog the app
// answered or routed never shows, so it is never witnessed: this is the
// before-and-after evidence for the dialog router.
//
// Modal dialogs are seen through the app's own hook, after its listeners have
// passed them. Modeless dialogs, which Show() rather than ShowModal(), are
// found by a timer that looks at the top-level windows. A native message box
// or file picker is drawn outside wxWidgets, where the timer cannot close it:
// it is answered as it opens, and still counted as shown.

#include "slic3r/GUI/JusPrin/Workspace/DialogListeners.hpp"
#include "slic3r/GUI/Widgets/ProgressDialog.hpp"

#include <boost/filesystem/path.hpp>
#include <wx/dialog.h>
#include <wx/dirdlg.h>
#include <wx/filedlg.h>
#include <wx/msgdlg.h>
#include <wx/timer.h>
#include <wx/weakref.h>

#include <iostream>
#include <memory>
#include <set>
#include <string>
#include <vector>

#ifdef __APPLE__
bool snapshot_native_window(void* native_view, const char* path);
#endif

namespace JusPrinTest {

class DialogWitness : public Slic3r::GUI::JusPrin::Workspace::UnansweredDialogObserver
{
public:
    explicit DialogWitness(boost::filesystem::path directory) : m_directory(std::move(directory))
    {
        Register();
    }
    // Outlives the app at exit, so its timer is left to the process.
    ~DialogWitness() override { m_timer.release(); }
    // Once the app exists: a timer cannot be made before it.
    void start()
    {
        if (m_timer)
            return;
        m_timer = std::make_unique<wxTimer>();
        m_timer->Bind(wxEVT_TIMER, [this](wxTimerEvent&) { tick(); });
        m_timer->Start(300);
    }

    // Every dialog seen so far, as "title | text", in order.
    const std::vector<std::string>& shown() const { return m_shown; }

protected:
    int Enter(wxDialog* dialog) override
    {
        start();
        report("modal", *dialog);
        if (dynamic_cast<wxMessageDialogBase*>(dialog) != nullptr) {
            int answer = wxID_CANCEL;
            Slic3r::GUI::JusPrin::Workspace::least_change_answer(Slic3r::GUI::JusPrin::Workspace::read_dialog(*dialog), answer);
            std::cerr << "HARNESS DIALOG CLOSED native '" << dialog->GetTitle().ToUTF8().data() << "' answer=" << answer << '\n';
            return answer;
        }
        if (dynamic_cast<wxFileDialogBase*>(dialog) != nullptr || dynamic_cast<wxDirDialogBase*>(dialog) != nullptr) {
            std::cerr << "HARNESS DIALOG CLOSED picker answer=" << wxID_CANCEL << '\n';
            return wxID_CANCEL;
        }
        return wxID_NONE;
    }

private:
    void report(const char* kind, wxDialog& dialog)
    {
//              reload recovery, native mutation, and the model follow-ups
//   --mcp     real TCP discovery/read and mutation using the shared runtime
//   --mcp-bridge  same native scenario through a persistent stdio subprocess
//   --mcp-setup   native setup-command lifetime, output and argument checks;
//                 uses this harness as a fixture, never edits client config
//   --dialog-routing <output-directory>
//                 makes OrcaSlicer raise its own dialogs through agent tools
//                 and checks none reaches the screen over the chat
//                 (dialog_routing_scenario.inc); pictures any that does
//   --dialog-witness <output-directory>
//                 with any mode: says on stderr which of OrcaSlicer's dialogs
//                 reached the screen (HARNESS DIALOG SHOWN), pictures each and
//                 closes it with the answer that changes least
//   --manual-mcp <fixture-directory>
//                 leaves a two-plate native fixture open for real MCP clients;
//                 exposes Orca's sidebar for native-edit/stale-revision checks;
            if (fs::exists(state->request_log) && !fs::is_empty(state->request_log)) {
                std::cerr << "--request-log needs an empty or new directory: " << state->request_log.string() << '\n';
                return 2;
            }
        }
        else if (argument == "--fake-printer")
            state->fake_printer = true;
        else if (argument == "--dialog-witness") {
            if (++index == argc) {
                std::cerr << "--dialog-witness requires an output directory\n";
                return 2;
            }
            fs::create_directories(fs::absolute(argv[index]));
            g_dialog_witness = std::make_unique<JusPrinTest::DialogWitness>(fs::absolute(argv[index]));
        }
        else if (argument == "--manual-unconfigured")
            state->mode = HarnessState::Mode::ManualUnconfigured;
        else if (argument == "--manual-tool-strip")
            state->mode = HarnessState::Mode::ManualToolStrip;
        else if (argument == "--file-corpus") {
            if (index + 2 >= argc) {
                std::cerr << "--dialog-routing requires an output directory\n";
                return 2;
            }
            state->mode      = HarnessState::Mode::PrintIssues;
            g_dialog_routing = true;
            fs::create_directories(fs::absolute(argv[index]));
            g_dialog_witness = std::make_unique<JusPrinTest::DialogWitness>(fs::absolute(argv[index]));
        }
        else if (argument == "--orca-messages") {
            if (++index == argc) {
                std::cerr << "--orca-messages requires an output directory\n";
                return 2;
            }
            state->mode        = HarnessState::Mode::PrintIssues;
            g_orca_messages    = true;
            state->capture_dir = fs::absolute(argv[index]);
            fs::create_directories(fs::absolute(argv[index]));
            g_dialog_witness = std::make_unique<JusPrinTest::DialogWitness>(fs::absolute(argv[index]));
        }
        else if (argument == "--orca-messages-pause") {
            if (++index == argc) {
                        self->check(self->m_notebook->GetSelectedPageName() == TAB_ID_PREPARE,
                                    "mcp_fixture_tab_survives_settle");
                        self->check(!self->m_plater->is_preview_shown(), "mcp_fixture_view_survives_settle");
                        // The hand-over screen is what gets photographed, so
                        // the page's own error pane is re-checked last.
                        self->check(!installed_shell()->agent_pane()->web_view().bridge_error_shown(),
                                    "mcp_fixture_agent_page_healthy_at_handover");
                        if (g_dialog_witness)
                            g_dialog_witness->start();
                        std::cerr << "HARNESS MCP FIXTURE READY failures=" << self->m_failures
                                  << " discovery=" << data_dir() << "/jusprin/mcp.json\n";

